parameters.functionScript:
// The page title is the browser TAB, and it is the one learner-facing string a
// Translation node cannot reach: `Page.title` is read off the node's PARAMETERS at
// export time into the router index (utils/exporter/router.ts), and the Router hands
// that to Noodl.SEO.setTitle on mount. A connection to the port is silently ignored —
// measured, TASK-L161 §1: with the parameter removed and a Translation wired, the tab
// read "Home", the component name.
//
// So the parameter stays as the BUILD-TIME FALLBACK (the router index needs it, and it
// is what the tab shows for the instant before this runs), and the translated value
// overrides it here. Same shape as the kit's built-in English: a fallback is not a
// second owner.
const t = Inputs.title;
if (typeof t === 'string' && t !== '' && typeof Noodl !== 'undefined' && Noodl.SEO) {
  Noodl.SEO.setTitle(t);
}

/*
 * WRITTEN, OR NOT YET (TASK-L171 §0b). `found` is undefined until the answer
 * arrives, so neither state draws while the lesson is on its way — the page does
 * not flash "not written yet" at somebody whose lesson is one request away.
 */
Outputs.hasLesson = Inputs.found === true;
Outputs.notWritten = Inputs.found === false;

/*
 * WHAT THEY SENT IN, UNDER THE CHALLENGE THAT ASKED FOR IT (TASK-L182).
 *
 * The product's ArtifactChallenge reads this learner's attempts for this concept
 * and shows the latest one's verdict with the earlier ones behind a toggle. Here
 * the attempts ride ON the section object, because the kit's Section node
 * spreads a section's fields into the renderer's props — so the challenge gets
 * them with no new port, and every other section passes through untouched.
 *
 * A pure derivation: it runs whenever the sections or the work arrive, and the
 * sections go out at once even before the work has come back, so the lesson
 * never waits on the programme to render.
 */
const sections = Array.isArray(Inputs.sections) ? Inputs.sections : null;
if (!sections) return;
const concept = String(Inputs.conceptId || '');
const work = Array.isArray(Inputs.work) ? Inputs.work : [];
const mine = work.filter((w) => w && w.source === 'artifact' && w.conceptId === concept);
Outputs.sections = sections.map((s) =>
  s && s.kind === 'artifact_challenge'
    ? Object.assign({}, s, {
        attempts: mine.filter((w) => !w.sectionId || w.sectionId === s.id).sort((a, b) => a.attempt - b.attempt)
      })
    : s
);

/*
 * THEY MARKED THIS STEP COMPLETE (TASK-L178). Runs on the close's `finish` only.
 * The step is the lesson this page served — never one named anywhere else — and
 * the learner is the session, on the backend's side.
 */
const conceptId = String(Inputs.conceptId || '');
if (!conceptId) return;
Outputs.conceptId = conceptId;
Outputs.state = 'saving';
Outputs.ask();

/*
 * IT COULD NOT BE MARKED COMPLETE (TASK-L178). They stay on the lesson, the
 * button comes back and the close says so. The product goes to the course on
 * any error, which leaves somebody believing a step is finished that is not.
 */
Outputs.state = 'failed';
